text:
PRTime date;

nsString authorValue;
nsString subjectValue;
nsString dateValue;

(void)aMsgHdr->GetDate(&date);
PRExplodedTime exploded;
PR_ExplodeTime(date, PR_LocalTimeParameters, &exploded);

mozilla::intl::DateTimeFormat::StyleBag style;
style.date = mozilla::Some(mozilla::intl::DateTimeFormat::Style::Short);
style.time = mozilla::Some(mozilla::intl::DateTimeFormat::Style::Long);
mozilla::intl::AppDateTimeFormat::Format(style, &exploded, dateValue);

(void)aMsgHdr->GetMime2DecodedAuthor(authorValue);
(void)aMsgHdr->GetMime2DecodedSubject(subjectValue);

nsCString buffer;
// this is big enough to hold a log entry.
// do this so we avoid growing and copying as we append to the log.
buffer.SetCapacity(512);

RefPtr<mozilla::intl::Localization> l10n =
    mozilla::intl::Localization::Create({"messenger/filterEditor.ftl"_ns},
                                        true);

nsAutoCString detectionErrorMessage;
rv = LocalizeMessage(l10n, "spam-message-detection-log"_ns,
                     {{"author"_ns, NS_ConvertUTF16toUTF8(authorValue)},
                      {"subject"_ns, NS_ConvertUTF16toUTF8(subjectValue)},
                      {"date"_ns, NS_ConvertUTF16toUTF8(dateValue)}},
                     detectionErrorMessage);
NS_ENSURE_SUCCESS(rv, rv);

buffer += detectionErrorMessage;
buffer += "\n";

if (aMoveMessage) {
  nsCString msgId;
  aMsgHdr->GetMessageId(msgId);

  nsCString folderURI;
  rv = GetSpamFolderURI(folderURI);
  NS_ENSURE_SUCCESS(rv, rv);

  nsAutoCString movedMessage;
  rv = LocalizeMessage(l10n, "moved-message-log"_ns,
                       {{"id"_ns, msgId}, {"folder"_ns, folderURI}},
                       movedMessage);
  NS_ENSURE_SUCCESS(rv, rv);
  buffer += movedMessage;
  buffer += "\n";
}

return LogJunkString(buffer.get());
